  "plan": "I'll append the solver setup and execution code.",
  "commands": [
    {
      "keystrokes": "cat >> solve_acopf.py << 'EOF'

# Initial point
x0 = pack_vars(Va_init, Vm_init, Pg_init, Qg_init)

print("\nSolving AC-OPF...")
print(f"Initial objective: ${objective(x0):.2f}/hr")

# Set up constraints
cons_eq = {'type': 'eq', 'fun': constraints_eq}
cons_ineq = {'type': 'ineq', 'fun': lambda x: -constraints_ineq(x)}

# Bounds
bounds = []
for i in range(n_bus):
    bounds.append((-np.pi, np.pi))
for i in range(n_bus):
    bounds.append((Vmin[i], Vmax[i]))
for i in range(n_gen):
    if gen_status[i]:
        bounds.append((Pmin[i], Pmax[i]))
    else:
        bounds.append((0, 0))
for i in range(n_gen):
    if gen_status[i]:
        bounds.append((Qmin[i], Qmax[i]))
    else:
        bounds.append((0, 0))

# Solve
result = minimize(
    objective,
    x0,
    method='SLSQP',
    bounds=bounds,
    constraints=[cons_eq, cons_ineq],
    options={'maxiter': 1000, 'ftol': 1e-6, 'disp': True}
)

print(f"\nOptimization: {result.message}")
print(f"Success: {result.success}")
print(f"Final objective: ${result.fun:.2f}/hr")

