print(f"Max P mismatch: {np.max(np.abs(P_mis))*baseMVA:.6f} MW")
print(f"Max Q mismatch: {np.max(np.abs(Q_mis))*baseMVA:.6f} MVAr")
EOF
",
      "duration": 0.1
    }
  ]
}

